float noise(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453123);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize pixel coordinates (from 0 to 1) and center them
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // Correct aspect ratio

    // Apply a time-varying rotation to evoke a sense of evolving perspective
    float angle = iTime * 0.5;
    mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    uv = rot * uv;

    // Convert to polar coordinates to create a radial pattern
    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // Create a swirling, rhythmic pattern with layered sine waves
    float pattern = sin(10.0 * r - iTime * 2.0 + sin(3.0 * a + iTime));
    pattern = pattern * 0.5 + 0.5; // Normalize to 0.0 - 1.0

    // Add subtle noise for an organic feel
    pattern += noise(uv * 10.0) * 0.2;

    // Choose a color palette that evolves with the pattern
    vec3 colorA = vec3(0.1, 0.2, 0.5); // Deep, cosmic blue
    vec3 colorB = vec3(1.0, 0.8, 0.2); // Warm, vibrant gold
    vec3 col = mix(colorA, colorB, pattern);

    // Apply a vignette effect to focus the viewer's attention toward the center
    col *= smoothstep(1.2, 0.5, r);

    fragColor = vec4(col, 1.0);
}
